1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	export type Damage = { itemType: string; amount: number };
8	export type Incident = { cause: string; damages: Damage[] };
9	
10	export type Step = {
11	  op: string;
12	  items?: Item[];
13	  policy?: number;
14	  incident?: Incident;
15	};
16	export type Customer = { yearsWithMHPCO: number };
17	export type Scenario = { customer: Customer; steps: Step[] };
18	
19	export type QuoteResult = { premium: number };
20	export type ClaimResult = { payout: number; remainingCap: number };
21	export type StepResult = QuoteResult | ClaimResult;
22	export type ScenarioResult = { results: StepResult[] };
23	
24	const BASE_PREMIUMS: Record<string, number> = {
25	  sword: 100,
26	  amulet: 60,
27	  staff: 80,
28	  potion: 40,
29	  rune: 25,
30	  moonstone: 25,
31	};
32	
33	const INSURANCE_VALUES: Record<string, number> = {
34	  sword: 1000,
35	  amulet: 600,
36	  staff: 800,
37	  potion: 400,
38	  rune: 250,
39	  moonstone: 250,
40	};
41	
42	const DEDUCTIBLE_PER_DAMAGE = 100;
43	const CAP_MULTIPLIER = 2;
44	const HIGH_ENCHANTMENT_PAYOUT_THRESHOLD = 8;
45	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
46	
47	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
48	const PROCESSING_FEE = 5;
49	
50	const CURSE_SURCHARGE_RATE = 0.5;
51	const HIGH_ENCHANTMENT_THRESHOLD = 5;
52	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
53	const LOYALTY_THRESHOLD_YEARS = 2;
54	const LOYALTY_DISCOUNT_RATE = 0.2;
55	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
56	
57	const BLOCK_SIZE = 3;
58	const BLOCK_BASE_PREMIUM = 60;
59	
60	const countByType = (items: Item[]): Map<string, number> => {
61	  const counts = new Map<string, number>();
62	  for (const item of items) {
63	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
64	  }
65	  return counts;
66	};
67	
68	const basePremiumForType = (type: string, count: number): number =>
69	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
70	
71	const policyBasePremium = (items: Item[]): number =>
72	  [...countByType(items)]
73	    .map(([type, count]) => basePremiumForType(type, count))
74	    .reduce((total, premium) => total + premium, 0);
75	
76	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
77	
78	const isCursed = (item: Item): boolean => item.cursed === true;
79	
80	const isHighlyEnchanted = (item: Item): boolean =>
81	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
82	
83	const curseSurcharge = (item: Item): number =>
84	  isCursed(item) ? itemBasePremium(item) * CURSE_SURCHARGE_RATE : 0;
85	
86	const highEnchantmentSurcharge = (item: Item): number =>
87	  isHighlyEnchanted(item)
88	    ? itemBasePremium(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
89	    : 0;
90	
91	const itemModifierSurcharges = (items: Item[]): number =>
92	  items
93	    .map((item) => curseSurcharge(item) + highEnchantmentSurcharge(item))
94	    .reduce((total, surcharge) => total + surcharge, 0);
95	
96	const isLoyalCustomer = (customer: Customer): boolean =>
97	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
98	
99	// Policy-wide modifiers are rates applied to the policy base premium.
100	// Surcharges are positive, discounts negative; they sum to one net rate.
101	const policyModifierRates = (
102	  customer: Customer,
103	  isFollowUpContract: boolean,
104	): number[] => [
105	  FIRST_INSURANCE_SURCHARGE_RATE,
106	  isLoyalCustomer(customer) ? -LOYALTY_DISCOUNT_RATE : 0,
107	  isFollowUpContract ? -FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0,
108	];
109	
110	const netPolicyModifierRate = (
111	  customer: Customer,
112	  isFollowUpContract: boolean,
113	): number =>
114	  policyModifierRates(customer, isFollowUpContract).reduce(
115	    (total, rate) => total + rate,
116	    0,
117	  );
118	
119	const quotePremium = (
120	  customer: Customer,
121	  items: Item[] = [],
122	  isFollowUpContract = false,
123	): number => {
124	  const policyBase = policyBasePremium(items);
125	  const policyModifiers =
126	    policyBase * netPolicyModifierRate(customer, isFollowUpContract);
127	  return Math.ceil(
128	    policyBase +
129	      itemModifierSurcharges(items) +
130	      policyModifiers +
131	      PROCESSING_FEE,
132	  );
133	};
134	
135	type Policy = { items: Item[]; remainingCap: number };
136	
137	const insuranceSum = (items: Item[]): number =>
138	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
139	
140	const isHighlyEnchantedForPayout = (item: Item): boolean =>
141	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_PAYOUT_THRESHOLD;
142	
143	const reimbursedAmount = (item: Item, damage: Damage): number =>
144	  isHighlyEnchantedForPayout(item)
145	    ? damage.amount * HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
146	    : damage.amount;
147	
148	const damagePayout = (item: Item, damage: Damage): number =>
149	  reimbursedAmount(item, damage) - DEDUCTIBLE_PER_DAMAGE;
150	
151	const settleClaim = (policy: Policy, incident: Incident): ClaimResult => {
152	  const payout = Math.floor(
153	    incident.damages.reduce((total, damage) => {
154	      const item = policy.items.find((i) => i.type === damage.itemType)!;
155	      return total + damagePayout(item, damage);
156	    }, 0),
157	  );
158	  policy.remainingCap -= payout;
159	  return { payout, remainingCap: policy.remainingCap };
160	};
161	
162	const openPolicy = (items: Item[]): Policy => ({
163	  items,
164	  remainingCap: insuranceSum(items) * CAP_MULTIPLIER,
165	});
166	
167	export const runScenario = (scenario: Scenario): ScenarioResult => {
168	  // Policies are keyed by the index of the quote step that opened them;
169	  // a claim step names that index in `step.policy`.
170	  const policies = new Map<number, Policy>();
171	
172	  const quoteStep = (step: Step, stepIndex: number): QuoteResult => {
173	    // A quote is a follow-up when some earlier step already opened a policy,
174	    // so this must be read before the new policy is registered below.
175	    const isFollowUpContract = policies.size > 0;
176	    const items = step.items ?? [];
177	    policies.set(stepIndex, openPolicy(items));
178	    return {
179	      premium: quotePremium(scenario.customer, items, isFollowUpContract),
180	    };
181	  };
182	
183	  const claimStep = (step: Step): ClaimResult =>
184	    settleClaim(policies.get(step.policy ?? -1)!, step.incident!);
185	
186	  const results = scenario.steps.map((step, stepIndex): StepResult =>
187	    step.op === "claim" ? claimStep(step) : quoteStep(step, stepIndex),
188	  );
189	
190	  return { results };
191	};
